// emitEndpointEvents sends an xds.EndpointEvent of the given type to the
// endpoint event channel for every endpoint found in the namespace. Endpoints
// are resolved from either the CiliumEndpoint or CiliumEndpointSlice resource
// depending on whether CiliumEndpointSlice mode is enabled.
func (ops *EnrollmentReconciler) emitEndpointEvents(ctx context.Context, namespace string, eventType xds.EndpointEventType) {
	if ops.endpointEventCh == nil {
		return
	}
	for _, cep := range ops.listEndpointsInNamespace(ctx, namespace) {
		ops.endpointEventCh <- &xds.EndpointEvent{
			Type:           eventType,
			CiliumEndpoint: cep,
		}
	}
