// listEndpointsInNamespace returns the CiliumEndpoints belonging to the given
// namespace, resolved from the appropriate resource store.
func (ops *EnrollmentReconciler) listEndpointsInNamespace(ctx context.Context, namespace string) []*types.CiliumEndpoint {
	var eps []*types.CiliumEndpoint

	if option.Config.EnableCiliumEndpointSlice {
		if ops.ciliumEndpointSliceResource == nil {
			return nil
		}
		store, err := ops.ciliumEndpointSliceResource.Store(ctx)
		if err != nil {
			ops.logger.Error("Failed to get CiliumEndpointSlice store",
				logfields.K8sNamespace, namespace,
				logfields.Error, err,
			)
			return nil
		}
		for _, ces := range store.List() {
			if ces.Namespace != namespace {
				continue
			}
			for i := range ces.Endpoints {
				eps = append(eps, k8s.ConvertCoreCiliumEndpointToTypesCiliumEndpoint(&ces.Endpoints[i], ces.Namespace))
			}
		}
		return eps
	}

	if ops.ciliumEndpointResource == nil {
		return nil
	}
	store, err := ops.ciliumEndpointResource.Store(ctx)
	if err != nil {
		ops.logger.Error("Failed to get CiliumEndpoint store",
			logfields.K8sNamespace, namespace,
			logfields.Error, err,
		)
		return nil
	}
	for _, cep := range store.List() {
		if cep.Namespace != namespace {
			continue
		}
		eps = append(eps, cep)
	}
	return eps
